// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz the caller address to ensure we treat any caller; the property is that version() always returns "1.0.0"
    function testFuzz_property(address caller) public {
        // keep caller wide but avoid zero address to ensure realistic caller
        vm.assume(caller != address(0));

        // Call the external view function from an arbitrary caller (prank ensures msg.sender is varied)
        vm.prank(caller);
        bool ok;
        string memory returned;
        try c.version() returns (string memory v) {
            ok = true;
            returned = v;
        } catch {
            ok = false;
            returned = "";
        }

        // The correct contract always returns the literal "1.0.0" and does not revert for any caller.
        // This single assertion will hold for the reference and fail for the mutant that returns "2.0.0" for some inputs.
        assertTrue(ok && (keccak256(bytes(returned)) == keccak256(bytes("1.0.0"))));
    }
}

