pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the caller address to ensure we call from arbitrary EOA callers
    function testFuzz_property(address caller) public {
        // keep caller within normal address space (non-zero helps avoid trivial edge-case)
        vm.assume(caller != address(0));

        // call the external view function version() from a fuzzed caller
        bool ok;
        string memory v;
        try c.version() returns (string memory s) {
            ok = true;
            v = s;
        } catch {
            ok = false;
            v = "";
        }

        // The universal property: the reference contract always returns a non-empty string on success.
        // We assert that if the call succeeded, the returned string's length is > 0.
        if (ok) {
            bytes memory b = bytes(v);
            assertTrue(b.length > 0);
        } else {
            // If the call reverted, fail the assertion (reference never reverts, so this will fail on revert mutants)
            assertTrue(false);
        }
    }
}

