pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed parameter included to satisfy the requirement that the fuzzer can search input space;
    // the version() function takes no args, but we include a fuzzed uint256 to let the fuzzer vary inputs
    // so it can explore different execution contexts (still the property is universal over calls).
    function testFuzz_property(uint256 /*unused_fuzzed*/ ) public {
        // No assumptions needed; keep domain wide so fuzzing can discover differing behavior.

        // Call version() and capture its returned string via try/catch (not necessary for revert here,
        // but using direct call to read the return value). We'll call and compare to the expected exact
        // string "1.0.0".

        string memory v = c.version();

        // Single assertion: the reference always returns exactly "1.0.0"; the mutant returns a different
        // string for some inputs (e.g., "v1.0.0"), so this assert will fail on the mutant for some fuzzed runs.
        assertTrue(keccak256(bytes(v)) == keccak256(bytes("1.0.0")));
    }
}

