pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed param forces the fuzzer to explore inputs; version() is pure and takes no args,
    // but we must include at least one fuzz param per instructions. The param does not
    // influence c.version(), but lets the fuzzer vary execution and find the mutant.
    function testFuzz_property(uint256 fuzz) public {
        // keep fuzz wide; no restrictive assumes so fuzzer can find differing mutant behavior
        // Call the external view function and capture success and returned string via try/catch
        bool ok;
        string memory v;
        try c.version() returns (string memory s) {
            ok = true;
            v = s;
        } catch {
            ok = false;
            v = "";
        }

        // General invariant: the reference always returns exactly "1.0.0" (and does not revert).
        // The mutant that returns "1.0.0+meta" will violate this for some fuzz input runs
        // (the fuzz param forces exploration; here we assert the property reading c's public API).
        assertTrue(ok && (keccak256(bytes(v)) == keccak256(bytes("1.0.0"))));
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the depositorAccount that should be honored by the reference implementation
    function testFuzz_property(address fuzzedDepositor) public {
        // keep wide domain but avoid zero address to be realistic
        vm.assume(fuzzedDepositor != address(0));

        // set the depositorAccount storage slot to the fuzzed address
        // The reference contract declares `address public depositorAccount;` so
        // we can set it by using a prank from an account that can write it.
        // There is no setter; but tests may directly write via vm.prank + low-level call
        // However, we are not allowed vm.store. Instead, we can simulate setting by
        // performing a delegatecall style: but simplest is to use selfdestruct pattern is
        // not allowed. Instead we rely on the fact that depositorAccount is public and
        // initially zero; to create the distinguishing scenario we will call setL1BlockValues
        // from fuzzedDepositor and observe acceptance vs rejection. The reference requires
        // msg.sender == depositorAccount (initially zero), so any non-zero fuzzedDepositor
        // must be rejected by reference, while mutant may accept if fuzzedDepositor equals
        // the constant DEPOSITOR_ACCOUNT. To ensure we test both behaviors, we pick fuzzedDepositor
        // freely and assert that the reference rejects the call (ok==false) for any non-zero
        // depositorAccount because depositorAccount starts as zero in the reference contract.

        // Prepare arbitrary parameters for setL1BlockValues
        uint64 _number = 1;
        uint64 _timestamp = 2;
        uint256 _basefee = 3;
        bytes32 _hash = bytes32(uint256(4));
        uint64 _sequenceNumber = 5;
        bytes32 _batcherHash = bytes32(uint256(6));
        uint256 _l1FeeOverhead = 7;
        uint256 _l1FeeScalar = 8;

        bool ok;
        vm.prank(fuzzedDepositor);
        try c.setL1BlockValues(
            _number,
            _timestamp,
            _basefee,
            _hash,
            _sequenceNumber,
            _batcherHash,
            _l1FeeOverhead,
            _l1FeeScalar
        ) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: reference C has depositorAccount==address(0) initially, so any non-zero
        // caller must be rejected (ok == false). The mutant that compares msg.sender to the
        // hard-coded DEPOSITOR_ACCOUNT will accept if fuzzedDepositor equals that constant; thus
        // the assertion below will hold for the reference for all non-zero fuzzedDepositor, but
        // the mutant is breakable for some fuzzedDepositor values (specifically DEPOSITOR_ACCOUNT).
        assertTrue(ok == false);
    }
}
